=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md (zero wait states, no state machine).
module apb_regs #(
  parameter ADDR_WIDTH = 8,
  parameter DATA_WIDTH = 32
) (
  input  wire                    pclk,
  input  wire                    presetn,
  input  wire [ADDR_WIDTH-1:0]   paddr,
  input  wire                    psel,
  input  wire                    penable,
  input  wire                    pwrite,
  input  wire [DATA_WIDTH-1:0]   pwdata,
  input  wire [DATA_WIDTH/8-1:0] pstrb,
  output wire [DATA_WIDTH-1:0]   prdata,
  output wire                    pready,
  output wire                    pslverr
);

  // Byte merge: copy each byte of data whose strobe bit is set.
  function [DATA_WIDTH-1:0] merge;
    input [DATA_WIDTH-1:0]   old_v;
    input [DATA_WIDTH-1:0]   data;
    input [DATA_WIDTH/8-1:0] strb;
    integer i;
    begin
      merge = old_v;
      for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
        if (strb[i]) begin
          merge[8*i +: 8] = data[8*i +: 8];
        end
      end
    end
  endfunction

  // Completion cycle: pready is always high, so access is the completing cycle.
  wire       access = psel && penable;
  // Mapped: word aligned and inside 0x0..0xC.
  wire       mapped = (paddr[1:0] == 2'b00) &&
                      ((paddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] idx    = paddr[3:2];
  wire       wr_en  = access && pwrite && mapped;
  wire       rd_en  = access && !pwrite && mapped;

  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else begin
      if (wr_en && (idx == 2'd0)) reg0 <= merge(reg0, pwdata, pstrb);
      if (wr_en && (idx == 2'd1)) reg1 <= merge(reg1, pwdata, pstrb);
      if (wr_en && (idx == 2'd2)) reg2 <= merge(reg2, pwdata, pstrb);
      if (wr_en && (idx == 2'd3)) reg3 <= merge(reg3, pwdata, pstrb);
    end
  end

  reg [DATA_WIDTH-1:0] rd_mux;
  always @(*) begin
    case (idx)
      2'd0:    rd_mux = reg0;
      2'd1:    rd_mux = reg1;
      2'd2:    rd_mux = reg2;
      2'd3:    rd_mux = reg3;
      default: rd_mux = {DATA_WIDTH{1'b0}};
    endcase
  end

  assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
  assign pready  = 1'b1;
  assign pslverr = access && !mapped;

`ifdef FORMAL
  // Design-intent assertions (not proven here).
  always @(*) begin
    assert (pready == 1'b1);
    if (!access) begin
      assert (prdata == {DATA_WIDTH{1'b0}});
      assert (pslverr == 1'b0);
    end
    if (access && !mapped) begin
      assert (pslverr == 1'b1);
      assert (prdata == {DATA_WIDTH{1'b0}});
    end
  end
`endif

endmodule
`default_nettype wire
=== END FILE ===
