`timescale 1ns/1ps
`default_nettype none
// Self-checking testbench for apb_regs.
module apb_regs_tb;
  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer passed;
  integer failed;
  integer s;
  integer k;
  reg [8*64-1:0] nonce;
  reg [31:0] model [0:3];

  apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
    .pclk    (pclk),
    .presetn (presetn),
    .paddr   (paddr),
    .psel    (psel),
    .penable (penable),
    .pwrite  (pwrite),
    .pwdata  (pwdata),
    .pstrb   (pstrb),
    .prdata  (prdata),
    .pready  (pready),
    .pslverr (pslverr)
  );

  initial begin
    pclk = 1'b0;
    forever #5 pclk = ~pclk;
  end

  // Independent reference decode: aligned and below 0x10.
  function tb_mapped;
    input [7:0] a;
    begin
      tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
    end
  endfunction

  // Independent reference byte merge.
  function [31:0] merge_tb;
    input [31:0] o;
    input [31:0] d;
    input [3:0]  st;
    begin
      merge_tb[7:0]   = st[0] ? d[7:0]   : o[7:0];
      merge_tb[15:8]  = st[1] ? d[15:8]  : o[15:8];
      merge_tb[23:16] = st[2] ? d[23:16] : o[23:16];
      merge_tb[31:24] = st[3] ? d[31:24] : o[31:24];
    end
  endfunction

  task chk1;
    input         got;
    input         exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed: got %b expected %b (paddr=%h psel=%b penable=%b pwrite=%b) at %0t",
               id, got, exp, paddr, psel, penable, pwrite, $time);
      end
    end
  endtask

  task chk32;
    input [31:0]  got;
    input [31:0]  exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed: got %h expected %h (paddr=%h psel=%b penable=%b pwrite=%b) at %0t",
               id, got, exp, paddr, psel, penable, pwrite, $time);
      end
    end
  endtask

  task chk_quiet;
    input integer id;
    begin
      chk32(prdata, 32'h0000_0000, id);
      chk1(pslverr, 1'b0, id + 1);
    end
  endtask

  task apb_write;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    reg m;
    begin
      m = tb_mapped(addr);
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
      paddr = addr; pwdata = data; pstrb = strb;
      #1;
      chk_quiet(20);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready, 1'b1, 30);
      chk1(pslverr, ~m, 31);
      chk32(prdata, 32'h0000_0000, 32);
      if (m) model[addr[3:2]] = merge_tb(model[addr[3:2]], data, strb);
    end
  endtask

  task apb_read;
    input [7:0] addr;
    reg m;
    reg [31:0] exp;
    begin
      m = tb_mapped(addr);
      exp = m ? model[addr[3:2]] : 32'h0000_0000;
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
      paddr = addr; pwdata = 32'hA5A5_5A5A; pstrb = 4'h0;
      #1;
      chk_quiet(22);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready, 1'b1, 40);
      chk1(pslverr, ~m, 41);
      chk32(prdata, exp, 42);
    end
  endtask

  task idle;
    input integer n;
    begin
      for (k = 0; k < n; k = k + 1) begin
        @(negedge pclk);
        psel = 1'b0; penable = 1'b0;
        #1;
        chk_quiet(50);
      end
    end
  endtask

  // psel low with a write-looking bus: must not change any register.
  task idle_dirty;
    input integer n;
    begin
      for (k = 0; k < n; k = k + 1) begin
        @(negedge pclk);
        psel = 1'b0; penable = 1'b0; pwrite = 1'b1;
        paddr = 8'h04; pwdata = 32'hFFFF_FFFF; pstrb = 4'hF;
        #1;
        chk_quiet(52);
      end
    end
  endtask

  task read_all;
    begin
      apb_read(8'h00);
      apb_read(8'h04);
      apb_read(8'h08);
      apb_read(8'h0C);
    end
  endtask

  task bad_write;
    input [7:0] addr;
    begin
      apb_write(addr, 32'hFFFF_FFFF, 4'hF);
    end
  endtask

  task do_reset;
    begin
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0; presetn = 1'b0;
      #1;
      chk_quiet(10);
      @(negedge pclk);
      #1;
      chk_quiet(10);
      @(negedge pclk);
      presetn = 1'b1;
      for (s = 0; s < 4; s = s + 1) model[s[1:0]] = 32'h0000_0000;
      #1;
      chk_quiet(12);
    end
  endtask

  initial begin
    presetn = 1'b0;
    paddr   = 8'h00;
    psel    = 1'b0;
    penable = 1'b0;
    pwrite  = 1'b0;
    pwdata  = 32'h0000_0000;
    pstrb   = 4'h0;
    passed  = 0;
    failed  = 0;
    nonce   = {64{8'h00}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};
    for (s = 0; s < 4; s = s + 1) model[s[1:0]] = 32'h0000_0000;

    // Initial reset: outputs quiet.
    repeat (3) begin
      @(negedge pclk);
      #1;
      chk_quiet(10);
    end
    @(negedge pclk);
    presetn = 1'b1;
    idle(2);

    // Reset values.
    read_all;

    // Full-word write then read of every register.
    apb_write(8'h00, 32'hA0A0_0001, 4'hF);
    apb_write(8'h04, 32'hB1B1_0002, 4'hF);
    apb_write(8'h08, 32'hC2C2_0003, 4'hF);
    apb_write(8'h0C, 32'hD3D3_0004, 4'hF);
    read_all;

    // Back-to-back transfers, then idle gaps.
    apb_write(8'h04, 32'h1357_9BDF, 4'hF);
    apb_read(8'h04);
    apb_write(8'h08, 32'h2468_ACE0, 4'hF);
    apb_write(8'h0C, 32'hFEDC_BA98, 4'hF);
    apb_read(8'h08);
    apb_read(8'h0C);
    apb_read(8'h00);
    idle(3);
    apb_read(8'h04);
    idle(1);
    apb_write(8'h00, 32'h0F0F_F0F0, 4'hF);
    idle(2);
    apb_read(8'h00);

    // Every strobe pattern, including none.
    for (s = 0; s < 16; s = s + 1) begin
      apb_write(8'h08, {s[7:0], ~s[7:0], s[7:0] ^ 8'h5A, s[7:0] ^ 8'hC3}, s[3:0]);
      apb_read(8'h08);
    end
    apb_write(8'h00, 32'hFFFF_FFFF, 4'b0101);
    apb_write(8'h0C, 32'h0000_0000, 4'b1000);
    apb_write(8'h04, 32'h0000_0000, 4'b0000);
    read_all;

    // Unmapped writes: misaligned and out of range. No register changes.
    bad_write(8'h01);
    bad_write(8'h02);
    bad_write(8'h03);
    bad_write(8'h05);
    bad_write(8'h0E);
    bad_write(8'h0F);
    bad_write(8'h10);
    bad_write(8'h14);
    bad_write(8'h18);
    bad_write(8'h1C);
    bad_write(8'h40);
    bad_write(8'h80);
    bad_write(8'hF0);
    bad_write(8'hFC);
    bad_write(8'hFF);
    apb_write(8'h11, 32'h1234_5678, 4'h0);
    read_all;

    // Unmapped reads: zero data with pslverr.
    apb_read(8'h01);
    apb_read(8'h06);
    apb_read(8'h0B);
    apb_read(8'h10);
    apb_read(8'h14);
    apb_read(8'h1C);
    apb_read(8'h80);
    apb_read(8'hFC);
    apb_read(8'hFF);
    idle(2);

    // Bus activity with psel low changes nothing.
    idle_dirty(3);
    read_all;

    // Reset again, with registers holding non-zero values.
    apb_write(8'h00, 32'h1111_1111, 4'hF);
    apb_write(8'h04, 32'h2222_2222, 4'hF);
    do_reset;
    idle(1);
    read_all;
    apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
    apb_read(8'h0C);
    idle(2);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: the run must end well before this.
  initial begin
    #1000000;
    $error("watchdog: simulation did not finish");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

endmodule
`default_nettype wire
=== END FILE ===
